import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'
import { DashboardSkeleton } from './DashboardSkeleton'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')

  if (!res.ok) {
    throw new Error('Failed to fetch dashboard data')
  }

  return res.json()
}

async function DashboardContent() {
  const data = await getDashboardData()

  return (
    <div className="dashboard-content">
      <CardStats
        totalRevenue={data.totalRevenue}
        totalInvoices={data.totalInvoices}
      />
      <RevenueChart revenue={data.revenue} />
      <LatestInvoices invoices={data.invoices} />
    </div>
  )
}

export default function Page() {
  return (
    <main className="dashboard">
      <header className="dashboard-header">
      <h1>Dashboard</h1>
        <p>Your business at a glance</p>
      </header>
      <Suspense fallback={<DashboardSkeleton />}>
        <DashboardContent />
      </Suspense>
    </main>
  )
}
function SkeletonLine({ className = '' }: { className?: string }) {
  return <span className={`dashboard-skeleton__line ${className}`} />
}

export function DashboardSkeleton() {
  return (
    <div
      className="dashboard-skeleton"
      role="status"
      aria-label="Loading dashboard data"
    >
      <div className="grid grid-cols-2 gap-4" aria-hidden="true">
        {[0, 1].map((card) => (
          <div className="card dashboard-skeleton__card" key={card}>
            <SkeletonLine className="dashboard-skeleton__line--label" />
            <SkeletonLine className="dashboard-skeleton__line--value" />
          </div>
        ))}
      </div>

      <section className="chart dashboard-skeleton__panel" aria-hidden="true">
        <SkeletonLine className="dashboard-skeleton__line--heading" />
        <div className="dashboard-skeleton__chart">
          {[42, 68, 51, 82, 60, 92, 73, 100].map((height, index) => (
            <span
              className="dashboard-skeleton__bar"
              key={index}
              style={{ height: `${height}%` }}
            />
          ))}
        </div>
      </section>

      <section
        className="invoices dashboard-skeleton__panel"
        aria-hidden="true"
      >
        <SkeletonLine className="dashboard-skeleton__line--heading" />
        <div className="dashboard-skeleton__rows">
          {[0, 1, 2, 3].map((row) => (
            <div className="dashboard-skeleton__row" key={row}>
              <SkeletonLine className="dashboard-skeleton__line--name" />
              <SkeletonLine className="dashboard-skeleton__line--amount" />
            </div>
          ))}
        </div>
      </section>
    </div>
  )
}

